//! Checking a project against what a library says it needs.
//!
//! These checks are advisory. Nothing here blocks an install, because a project can be
//! laid out in ways this cannot read, and being wrong must never stop someone using the
//! library. The value is catching the common mistakes before they turn into a linker
//! error that says nothing useful.
//!
//! Two sources of truth are read, both generated by CubeMX:
//!
//! ```text
//! stm32xxxx_hal_conf.h   which HAL modules are compiled in
//! *.ioc                  which peripherals and middleware are configured
//! ```

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::LazyLock;

use regex::Regex;

use crate::files;
use crate::manifest::Manifest;
use crate::paths;
use crate::target::Finding;

/// "#define HAL_SPI_MODULE_ENABLED", but not the commented out form CubeMX leaves behind
/// for modules that are switched off.
static HAL_MODULE: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"(?m)^[ \t\r\x0b\x0c]*#define[ \t\r\x0b\x0c]+HAL_([A-Z0-9_]+)_MODULE_ENABLED")
        .expect("a valid pattern")
});

/// CubeMX records configured peripherals as Mcu.IP0=SPI1, Mcu.IP1=FREERTOS, ...
static IOC_IP: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(?m)^Mcu\.IP\d+=(.+)$").expect("a valid pattern"));

const SEARCH_DEPTH: usize = 4;

/// Find files matching a pattern, without walking the whole disk.
fn find(project_root: &Path, pattern: &str) -> Vec<PathBuf> {
    let mut found = Vec::new();
    let mut level = vec![project_root.to_path_buf()];

    for _ in 0..SEARCH_DEPTH {
        let mut next = Vec::new();

        for folder in &level {
            let Ok(entries) = fs::read_dir(folder) else {
                continue;
            };

            let mut names: Vec<_> = entries.flatten().collect();
            names.sort_by_key(|entry| entry.file_name());

            for entry in names {
                let path = entry.path();

                if path.is_dir() {
                    next.push(path);
                } else if paths::name_matches(&entry.file_name().to_string_lossy(), pattern) {
                    found.push(path);
                }
            }
        }

        level = next;
    }

    found
}

/// The CubeMX generated HAL configuration header, when there is one.
pub fn find_hal_conf(project_root: &Path) -> Option<PathBuf> {
    find(project_root, "stm32*_hal_conf.h").into_iter().next()
}

/// The CubeMX project file, when there is one.
pub fn find_ioc(project_root: &Path) -> Option<PathBuf> {
    find(project_root, "*.ioc").into_iter().next()
}

/// Names of HAL modules switched on, lower case, for example spi and gpio.
pub fn enabled_hal_modules(hal_conf: Option<&Path>) -> Vec<String> {
    let Some(text) = hal_conf.and_then(|path| files::read_lossy(path).ok()) else {
        return Vec::new();
    };

    HAL_MODULE
        .captures_iter(&text)
        .map(|found| found[1].to_lowercase())
        .collect()
}

/// Peripherals and middleware CubeMX has configured, lower case.
pub fn configured_peripherals(ioc: Option<&Path>) -> Vec<String> {
    let Some(text) = ioc.and_then(|path| files::read_lossy(path).ok()) else {
        return Vec::new();
    };

    IOC_IP
        .captures_iter(&text)
        .map(|found| found[1].trim().to_lowercase())
        .collect()
}

/// Which operating system the project uses, if any.
///
/// Looks at what CubeMX configured first, then falls back to looking for the headers,
/// since a project can carry an RTOS that CubeMX did not add.
pub fn detect_rtos(project_root: &Path, peripherals: &[String]) -> Option<&'static str> {
    if peripherals.iter().any(|name| name.contains("freertos")) {
        return Some("freertos");
    }

    if peripherals.iter().any(|name| name.contains("threadx")) {
        return Some("threadx");
    }

    if !find(project_root, "cmsis_os2.h").is_empty() {
        return Some("cmsis-os2");
    }

    if !find(project_root, "FreeRTOS.h").is_empty() {
        return Some("freertos");
    }

    if !find(project_root, "cmsis_os.h").is_empty() {
        return Some("cmsis-os2");
    }

    None
}

/// Compare a library's requirements against the project.
///
/// An empty list means either everything matched or there was nothing to match against.
pub fn check(manifest: &Manifest, project_root: &Path) -> Vec<Finding> {
    let part = manifest.part.stm32();
    let requires = &manifest.requires;
    let mut findings = Vec::new();

    if requires.libraries.is_empty()
        && part.hal_modules.is_empty()
        && requires.peripherals.is_empty()
        && !part.needs_rtos
    {
        return findings;
    }

    let hal_conf = find_hal_conf(project_root);
    let ioc = find_ioc(project_root);
    let modules = enabled_hal_modules(hal_conf.as_deref());
    let peripherals = configured_peripherals(ioc.as_deref());

    if hal_conf.is_none() && ioc.is_none() {
        findings.push(Finding::info(
            "Could not find a CubeMX project here, so nothing was verified.",
            "Run this from the root of your STM32 project to have it checked.",
        ));

        return findings;
    }

    // HAL modules, read from stm32xxxx_hal_conf.h
    if let Some(hal_conf) = &hal_conf {
        let name = hal_conf.file_name().unwrap_or_default().to_string_lossy();

        for module in &part.hal_modules {
            let upper = module.to_uppercase();

            if modules.contains(module) {
                findings.push(Finding::ok(format!("HAL {upper} module is enabled")));
            } else {
                findings.push(Finding::warn(
                    format!("HAL {upper} module is not enabled"),
                    format!("Uncomment HAL_{upper}_MODULE_ENABLED in {name}, or enable it in CubeMX and regenerate."),
                ));
            }
        }
    }

    // Peripherals, read from the .ioc. CubeMX names instances, so a library asking for
    // "spi" is satisfied by SPI1, SPI2 and so on, which is why this goes by prefix.
    if ioc.is_some() {
        for peripheral in &requires.peripherals {
            let upper = peripheral.kind.to_uppercase();

            if peripherals
                .iter()
                .any(|name| name.starts_with(&peripheral.kind))
            {
                findings.push(Finding::ok(format!("{upper} is configured")));
            } else {
                findings.push(Finding::warn(
                    format!("No {upper} found in your CubeMX configuration"),
                    format!("This library needs {}.", peripheral.describe()),
                ));
            }
        }
    }

    // Operating system
    if part.needs_rtos {
        match detect_rtos(project_root, &peripherals) {
            None => findings.push(Finding::warn(
                "This library needs an RTOS and none was found",
                format!(
                    "It expects {}. Enable it in CubeMX under Middleware.",
                    part.rtos
                ),
            )),
            Some(found) if part.rtos == "any" || part.rtos == found => {
                findings.push(Finding::ok(format!("{found} is present")));
            }
            Some(found) => findings.push(Finding::warn(
                format!(
                    "This library expects {}, but the project uses {found}",
                    part.rtos
                ),
                "It may still work, but it has not been tested that way.",
            )),
        }
    }

    findings
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::manifest::load;
    use crate::manifest::testing::library;
    use crate::platform::Platform;
    use crate::target::Level;

    const HAL_CONF: &str = "#define HAL_MODULE_ENABLED\n#define HAL_SPI_MODULE_ENABLED\n/* #define HAL_I2C_MODULE_ENABLED */\n#define HAL_GPIO_MODULE_ENABLED\n";

    fn project(hal_conf: Option<&str>, ioc: Option<&str>) -> tempfile::TempDir {
        let root = tempfile::tempdir().unwrap();
        fs::create_dir_all(root.path().join("Core/Inc")).unwrap();

        if let Some(text) = hal_conf {
            fs::write(root.path().join("Core/Inc/stm32f4xx_hal_conf.h"), text).unwrap();
        }

        if let Some(text) = ioc {
            fs::write(root.path().join("Proj.ioc"), text).unwrap();
        }

        root
    }

    fn findings(requires: &str, project: &Path) -> Vec<Finding> {
        let root = tempfile::tempdir().unwrap();
        let folder = library(
            root.path(),
            "demo",
            &format!("{requires}headers: [a.h]\n"),
            &["a.h"],
        );
        let manifest = load(&folder, Some(Platform::Stm32)).unwrap();

        check(&manifest, project)
    }

    #[test]
    fn hal_modules_are_read_and_a_commented_one_is_off() {
        let modules = enabled_hal_modules(Some(&{
            let root = project(Some(HAL_CONF), None);
            let path = root.path().join("Core/Inc/stm32f4xx_hal_conf.h");
            std::mem::forget(root);
            path
        }));

        assert!(modules.contains(&"spi".to_string()));
        assert!(modules.contains(&"gpio".to_string()));
        assert!(!modules.contains(&"i2c".to_string()));
    }

    #[test]
    fn a_module_that_is_off_is_warned_about_with_the_way_to_fix_it() {
        let root = project(Some(HAL_CONF), None);
        let found = findings(
            "stm32:\n  requires:\n    hal_modules: [spi, i2c]\n",
            root.path(),
        );

        assert_eq!(found[0].level, Level::Ok);
        assert_eq!(found[0].message, "HAL SPI module is enabled");
        assert_eq!(found[1].level, Level::Warn);
        assert_eq!(found[1].message, "HAL I2C module is not enabled");
        assert!(
            found[1]
                .hint
                .contains("Uncomment HAL_I2C_MODULE_ENABLED in stm32f4xx_hal_conf.h")
        );
    }

    #[test]
    fn a_peripheral_is_found_by_its_instances_in_the_ioc() {
        let root = project(None, Some("Mcu.IP0=SPI1\nMcu.IP1=NVIC\r\n"));
        let found = findings(
            "requires:\n  peripherals:\n    - spi\n    - type: i2c\n      note: fast\n",
            root.path(),
        );

        assert_eq!(found[0].message, "SPI is configured");
        assert_eq!(found[1].level, Level::Warn);
        assert_eq!(found[1].hint, "This library needs I2C, fast.");
    }

    #[test]
    fn an_rtos_is_found_in_the_ioc_or_by_its_headers() {
        let requires = "stm32:\n  requires:\n    rtos: freertos\n";

        let root = project(None, Some("Mcu.IP0=FREERTOS\n"));
        assert_eq!(
            findings(requires, root.path())[0].message,
            "freertos is present"
        );

        let root = project(None, Some("Mcu.IP0=SPI1\n"));
        assert_eq!(findings(requires, root.path())[0].level, Level::Warn);

        fs::write(root.path().join("Core/cmsis_os2.h"), "").unwrap();
        assert_eq!(
            findings(requires, root.path())[0].message,
            "This library expects freertos, but the project uses cmsis-os2"
        );
        assert_eq!(
            findings("stm32:\n  requires:\n    rtos: any\n", root.path())[0].level,
            Level::Ok
        );
    }

    #[test]
    fn nothing_to_read_is_said_and_never_stops_anything() {
        let root = project(None, None);
        let found = findings("stm32:\n  requires:\n    hal_modules: [spi]\n", root.path());

        assert_eq!(found[0].level, Level::Info);
        assert!(found[0].message.contains("nothing was verified"));
    }

    #[test]
    fn a_library_that_asks_for_nothing_is_not_checked() {
        let root = project(None, None);

        assert!(findings("", root.path()).is_empty());
    }

    #[test]
    fn a_hal_conf_is_found_a_few_folders_down() {
        let root = project(Some(HAL_CONF), None);

        assert!(find_hal_conf(root.path()).is_some());
    }
}
